document.addEventListener("DOMContentLoaded", function() {

    const row = document.querySelector(".bg-white.theme1 .container .row");

    if (row) {

        row.style.position = "relative";

        const overlay = document.createElement("div");
        overlay.style.position = "absolute";
        overlay.style.top = "0";
        overlay.style.left = "50%";
        overlay.style.transform = "translateX(-50%)";
        overlay.style.width = window.innerWidth + "px"; // عرض الشاشة الحقيقي
        overlay.style.height = "100%";
        overlay.style.backgroundImage = "url('https://up6.cc/2026/02/177162266558342.png')";
        overlay.style.backgroundSize = "cover";
        overlay.style.backgroundPosition = "center";
        overlay.style.backgroundRepeat = "no-repeat";
overlay.style.webkitMaskImage = "linear-gradient(to right, transparent 0%, black 8%, black 92%, transparent 100%)";
overlay.style.maskImage = "linear-gradient(to right, transparent 0%, black 8%, black 92%, transparent 100%)";
        overlay.style.pointerEvents = "none";
        overlay.style.zIndex = "5";
        overlay.style.opacity = "0.6";

        row.appendChild(overlay);

        // يتعدل لو تغير حجم الشاشة
        window.addEventListener("resize", function() {
            overlay.style.width = window.innerWidth + "px";
        });
    }

});

 


